    #[inductive(produce_start)]
    fn produce_start_inductive(pre: Self, post: Self) {
        let i = post.producer.get_Producing_0();
        assert(post.storage == pre.storage.remove(i));
        assert forall|j: nat| 0 <= j && j < post.len() implies
            post.valid_storage_at_idx(j) by {
            if j == i {
                assert(!post.storage.dom().contains(j));
            } else {
                assert(pre.valid_storage_at_idx(j));
                assert(post.storage.dom().contains(j));
            }
        }
    }

    #[inductive(produce_end)]
    fn produce_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
        let old_tail = pre.producer.get_Producing_0();
        let new_tail = post.tail;
        assert(post.storage == pre.storage.insert(old_tail, perm));
        assert forall|j: nat| 0 <= j && j < post.len() implies
            post.valid_storage_at_idx(j) by {
            if j == old_tail {
                assert(post.storage.dom().contains(j));
                assert(post.storage.index(j).is_init());
            } else if j == new_tail {
                assert(post.storage.dom().contains(j));
            } else {
                assert(pre.valid_storage_at_idx(j));
                assert(post.storage.dom().contains(j));
            }
        }
    }

    #[inductive(consume_start)]
    fn consume_start_inductive(pre: Self, post: Self) {
        let i = post.consumer.get_Consuming_0();
        assert(post.storage == pre.storage.remove(i));
        assert forall|j: nat| 0 <= j && j < post.len() implies
            post.valid_storage_at_idx(j) by {
            if j == i {
                assert(!post.storage.dom().contains(j));
            } else {
                assert(pre.valid_storage_at_idx(j));
                assert(post.storage.dom().contains(j));
            }
        }
    }

    #[inductive(consume_end)]
    fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
        let old_head = pre.consumer.get_Consuming_0();
        let new_head = post.head;
        assert(post.storage == pre.storage.insert(old_head, perm));
        assert forall|j: nat| 0 <= j && j < post.len() implies
            post.valid_storage_at_idx(j) by {
            if j == old_head {
                assert(post.storage.dom().contains(j));
                assert(post.storage.index(j).is_uninit());
            } else if j == new_head {
                assert(post.storage.dom().contains(j));
            } else {
                assert(pre.valid_storage_at_idx(j));
                assert(post.storage.dom().contains(j));
            }
        }
    }
}}


